package com.superwall.sdk.network.signing

/**
 * The roots the SDK trusts to authorise response-signing keys: the base64 of each root's 65-byte
 * uncompressed P-256 public key. Two, so a root can be retired without an outage: the backend signs
 * with [ACTIVE], and [STANDBY] is ready to take over.
 *
 * Generated by superwall/paywall-next `packages/response-signing/scripts/exportRootPublicKey.ts`
 * from each root's KMS key; paste the line it prints. Public keys only. `null` until the root's KMS
 * key exists, and with no roots nothing verifies.
 */
internal object ResponseSigningRoots {
    val ACTIVE: String? = null
    val STANDBY: String? = null

    /** The configured roots. One that doesn't decode to a P-256 point is left out. */
    val all: List<ResponseVerifier.TrustedRoot>
        get() = decode(listOfNotNull(ACTIVE, STANDBY))

    internal fun decode(encoded: List<String>): List<ResponseVerifier.TrustedRoot> =
        encoded
            .mapNotNull { StrictBase64.decode(it) }
            .filter { it.size == 65 && it[0].toInt() == 0x04 && ResponseVerifier.p256PublicKey(it) != null }
            .map { ResponseVerifier.TrustedRoot(it) }
}
